# Find where the edges start and end
start_idx = None
end_idx = None
for i, line in enumerate(lines):
    if line == 'The graph has the following edges:':
        start_idx = i + 1
    if line == 'Operation:':
        end_idx = i
        break

print(f"Edges start at line {start_idx}, end at line {end_idx}")
print(f"First few edge lines:")
for line in lines[start_idx:start_idx+5]:
    print(repr(line))
print(f"\nLast few edge lines before operation:")
for line in lines[end_idx-5:end_idx]:
    print(repr(line))

# Let's look for where the actual graph edges are - probably after the examples
# Search for lines containing " -> " which indicate edges
edge_lines = []
for i, line in enumerate(lines):
    if ' -> ' in line and not line.startswith('Here') and not line.startswith('The graph'):
        edge_lines.append((i, line))

print(f"Total edge-like lines found: {len(edge_lines)}")
print("First 20 edge lines:")
for idx, (i, line) in enumerate(edge_lines[:20]):
    print(f"Line {i}: {line}")
print("\nLast 20 edge lines:")
for idx, (i, line) in enumerate(edge_lines[-20:]):
    print(f"Line {i}: {line}")
